'.format(vertices[i][0], vertices[i][1], vertices[i][2])) f.write('vt {} {}
'.format(colors[i][0], colors[i][1])) for i in range(0, len(vertices), 4): f.write('f {}/{} {}/{} {}/{} {}/{}
